180	// root when RepoPath is empty or has gone away.
181	func ensureBoardTracked(t *store.Ticket, declaredRepo string) {
182		if t.BoardTracked {
183			if t.RepoPath == "" || !dirExists(t.RepoPath) {
184				if root := devboard.RepoRootFor(declaredRepo); root != "" {
185					t.RepoPath = root
186				}
187			}
188			return
189		}
190		if !devboard.Enabled() {
191			return // devboard is opt-in by dir presence; a first tracking is a no-op, not a create
192		}
193		t.BoardTracked = true
194		if s := os.Getenv("CLAUDE_CODE_SESSION_ID"); s != "" {
195			t.Session = s
196		}
197		if b := devboard.GitBranch(); b != "" {
198			t.Branch = b
199		}
200		if root := devboard.RepoRootFor(declaredRepo); root != "" {
201			t.RepoPath = root
202		}
203	}
204	
205	// ensureParentBoardTracked replicates legacy's devboardSyncEpic, called on
206	// every child start/resume/done: a child's parent epic never goes through
207	// its own start (epics can't occupy ## Now), so nothing else ever
208	// board-tracks it. Without this, an epic's own file is never created and
209	// children with nowhere to nest never render. No-ops for a standalone
210	// ticket (t.ParentID == "") or if the parent lookup fails — a dangling
211	// ParentID is reported by the caller's own checks, not silently patched
212	// here.
213	func ensureParentBoardTracked(ss *storeSession, t *store.Ticket) error {
214		if t.ParentID == "" {
215			return nil
216		}
217		parent, err := ss.s.Ticket(t.ParentID)
218		if err != nil {
219			return nil
220		}
221		ensureBoardTracked(parent, parent.Repo)
222		return ss.s.PutTicket(parent)
223	}
224	
225	// clearBoardTracked is untrack's store-side half. Render only ever writes
226	// the files it expects (every BoardTracked, non-child ticket); it never
227	// prunes a file that fell out of that set, so deleting a task file alone
228	// would leave it recreated on the next write that happens to re-render.
229	// No-op (not an error) when id doesn't resolve to a store ticket — a bare
230	// producer file (no worklog: join key) has nothing in the store to clear,
231	// and the caller deletes the file directly in that case.
232	func clearBoardTracked(wd model.Workdir, id string) error {
233		ss, err := openStoreForWrite(wd)
234		if err != nil {
235			return err
236		}
237		defer ss.close()
238		t, err := ss.s.TicketBySlug(id)
239		if store.IsNotFound(err) {
240			return nil
241		}
242		if err != nil {
243			return err
244		}
245		t.BoardTracked = false
246		return ss.commit(t)
247	}
248	
249	func dirExists(p string) bool {
250		if p == "" {
251			return false
252		}
253		fi, err := os.Stat(p)
254		return err == nil && fi.IsDir()
255	}
256	
257	// ticketBySlugOrErr resolves slug to a *store.Ticket, mapping a
258	// not-found lookup to notFoundErr (typically a package's own
259	// ErrIDNotFound sentinel) so callers keep their existing error-mapping
260	// switch statements unchanged between the legacy and store paths.
261	func (ss *storeSession) ticketBySlugOrErr(slug string, notFoundErr error) (*store.Ticket, error) {
262		t, err := ss.s.TicketBySlug(slug)
263		if store.IsNotFound(err) {
264			return nil, fmt.Errorf("%w: %q", notFoundErr, slug)
265		}
266		if err != nil {
267			return nil, err
268		}
269		return t, nil
270	}
